Q: AKS deployment consistently fail due to readiness probe status code 500 A: <p>Hi My solution Replace your <strong><code>Ping.aspx.cs</code></strong> with a simple health check:</p>
<pre><code>protected void Page_Load(object sender, EventArgs e)
{
    Response.Clear();
    Response.StatusCode = 200;
    Response.ContentType = &quot;text/plain&quot;;
    Response.Write(&quot;OK&quot;);
    Response.End();
}
</code></pre>
<p>Or even better, add basic dependency checks:</p>
<pre><code>protected void Page_Load(object sender, EventArgs e)
{
    try
    {
        // Add your health checks here
        // Example: Database connectivity
        // using (var connection = new SqlConnection(connectionString))
        // {
        //     connection.Open();
        // }

        Response.Clear();
        Response.StatusCode = 200;
        Response.ContentType = &quot;text/plain&quot;;
        Response.Write(&quot;Healthy&quot;);
        Response.End();
    }
    catch (Exception ex)
    {
        Response.Clear();
        Response.StatusCode = 503; // Service Unavailable
        Response.ContentType = &quot;text/plain&quot;;
        Response.Write($&quot;Unhealthy: {ex.Message}&quot;);
        Response.End();
    }
}
</code></pre>
<p>Hint alternative; Use ASP.NET</p>
<p>If you're on .NET Core/.NET 5+, use built-in health checks:</p>
<pre><code>builder.Services.AddHealthChecks();  
app.MapHealthChecks(&quot;/health/ready&quot;);
app.MapHealthChecks(&quot;/health/live&quot;);
</code></pre>
<p>Update your probe;</p>
<pre><code>readinessProbe:
  httpGet:
    path: /health/ready
    port: 443
    scheme: HTTPS
  initialDelaySeconds: 15
  timeoutSeconds: 2
  periodSeconds: 5
  successThreshold: 1
  failureThreshold: 12
</code></pre>
